            let colors = read_colors(colors).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            });
            for color in colors {
                let modified = color.darken(amount);
                println!("{}", modified.to_hsl_string());
            }
        },
        Some(Commands::Saturate { amount, colors }) => {
            let colors = read_colors(colors).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            });
            for color in colors {
                let modified = color.saturate(amount);
                println!("{}", modified.to_hsl_string());
            }
        },
        Some(Commands::Desaturate { amount, colors }) => {
            let colors = read_colors(colors).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            });
            for color in colors {
                let modified = color.desaturate(amount);
                println!("{}", modified.to_hsl_string());
            }
        },
        Some(Commands::Rotate { degrees, colors }) => {
            let colors = read_colors(colors).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            });
            for color in colors {
                let modified = color.rotate_hue(degrees);
                println!("{}", modified.to_hsl_string());
            }
        },
        Some(Commands::Complement { colors }) => {
            let colors = read_colors(colors).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            });
            for color in colors {
                let modified = color.rotate_hue(180.0);
                println!("{}", modified.to_hsl_string());
            }
        },
        Some(Commands::Mix { base_color, colors, colorspace, fraction }) => {
            let mut all_colors = vec![base_color];
            all_colors.extend(colors);
            let colors = read_colors(all_colors).unwrap_or_else(|e| {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            });
            if colors.is_empty() {
                return;
            }
            let base = &colors[0];
            for color in &colors[1..] {
                let mixed = base.mix(color, fraction, &colorspace);
                println!("{}", mixed.to_hsl_string());
            }
        },
        Some(Commands::Gray { lightness }) => {
            let color = Color::gray(lightness);
            println!("{}", color.to_hsl_string());
