                eprintln!("Error: {}", e);
                std::process::exit(1);
            });
            if colors.is_empty() {
                return;
            }
            let gradient = Color::gradient(&colors, number, &colorspace);
            for color in gradient {
                println!("{}", color.to_hsl_string());
            }
        },
        Some(Commands::Distinct { count, colors, metric, verbose: _ }) => {
            let initial_colors = if colors.is_empty() {
                None
            } else {
                Some(read_colors(colors).unwrap_or_else(|e| {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }))
            };
            let distinct = Color::distinct(count, initial_colors, &metric);
            for color in distinct {
                println!("{}", color.to_hsl_string());
            }
        },
        Some(Commands::List { sort }) => {
            commands::list_colors(&sort);
        },
        Some(Commands::Colorcheck) => {
            commands::colorcheck();
        },
