fn read_colors(colors: Vec<String>) -> anyhow::Result<Vec<Color>> {
    if colors.is_empty() {
        // Read from stdin
        let stdin = io::stdin();
        let reader = stdin.lock();
        let mut result = Vec::new();
        for line in reader.lines() {
            let line = line?;
            let line = line.trim();
            if !line.is_empty() {
                result.push(Color::parse(&line)?);
            }
        }
        Ok(result)
    } else {
        let mut result = Vec::new();
        for color_str in colors {
            result.push(Color::parse(&color_str)?);
        }
        Ok(result)
    }
}

fn print_color(color: &Color) {
    println!("{}", color.to_hsl_string());
}

fn format_color(color: &Color, format: &str) -> anyhow::Result<String> {
    match format {
        "hex" => Ok(color.to_hex_string()),
        "rgb" => Ok(color.to_rgb_string()),
        "rgb-float" => Ok(color.to_rgb_float_string()),
        "rgb-r" => Ok((color.r as u8).to_string()),
        "rgb-g" => Ok((color.g as u8).to_string()),
        "rgb-b" => Ok((color.b as u8).to_string()),
        "hsl" => Ok(color.to_hsl_string()),
        "hsl-hue" => Ok(format!("{:.1}", color.to_hsl().0)),
        "hsl-saturation" => Ok(format!("{:.1}", color.to_hsl().1 * 100.0)),
        "hsl-lightness" => Ok(format!("{:.1}", color.to_hsl().2 * 100.0)),
        "hsv" => Ok(color.to_hsv_string()),
        "lch" => Ok(color.to_lch_string()),
        "oklch" => Ok(color.to_oklch_string()),
        "lab" => Ok(color.to_lab_string()),
        "oklab" => Ok(color.to_oklab_string()),
        "cmyk" => Ok(color.to_cmyk_string()),
        "name" => Ok(color.to_color_name().unwrap_or_else(|| color.to_hex_string())),
        _ => anyhow::bail!("Unknown format: {}", format),
    }
}
