        if colors.len() == 1 {
            return vec![colors[0].clone()];
        }
        if count == 0 {
            return vec![];
        }
        if count == 1 {
            return vec![colors[0].clone()];
        }

        let mut result = Vec::new();
        let segment_size = (count as f64 - 1.0) / (colors.len() - 1) as f64;

        for i in 0..count {
            let pos = i as f64 / segment_size;
            let seg_index = pos.floor() as usize;
            let seg_index = seg_index.min(colors.len() - 2);
            let frac = pos - seg_index as f64;

            let color = colors[seg_index].mix(&colors[seg_index + 1], frac, colorspace);
            result.push(color);
        }
        result
    }

