            "hue" => {
                sorted.sort_by(|a, b| {
                    let (h1, _, _) = a.to_hsl();
                    let (h2, _, _) = b.to_hsl();
                    h1.partial_cmp(&h2).unwrap()
                });
            },
            "brightness" => {
                sorted.sort_by(|a, b| {
                    let (_, _, v1) = a.to_hsv();
                    let (_, _, v2) = b.to_hsv();
                    v1.partial_cmp(&v2).unwrap()
                });
            },
            "luminance" => {
                sorted.sort_by(|a, b| {
                    let l1 = a.luminance();
                    let l2 = b.luminance();
                    l1.partial_cmp(&l2).unwrap()
                });
            },
            "chroma" => {
