                    let (_, c1, _) = a.to_lch();
                    let (_, c2, _) = b.to_lch();
                    c1.partial_cmp(&c2).unwrap()
                });
            },
            "random" => {
                use rand::seq::SliceRandom;
                sorted.shuffle(&mut rand::thread_rng());
            },
            _ => {},
        }

