                // Protanopia (red-blind)
                let r = 0.567 * self.r + 0.433 * self.g;
                let g = 0.558 * self.r + 0.442 * self.g;
                let b = 0.0 * self.r + 0.242 * self.b;
                (r, g, b)
            },
            "deuter" | "deuteranopia" => {
                // Deuteranopia (green-blind)
                let r = 0.625 * self.r + 0.375 * self.g;
                let g = 0.7 * self.r + 0.3 * self.g;
                let b = 0.0 * self.r + 1.0 * self.b;
                (r, g, b)
            },
            "trit" | "tritanopia" => {
                // Tritanopia (blue-blind)
                let r = 0.95 * self.r + 0.05 * self.b;
                let g = 0.433 * self.r + 0.567 * self.g;
                let b = 0.475 * self.g + 0.525 * self.b;
                (r, g, b)
            },
            _ => (self.r, self.g, self.b),
        };

        Color::new(r.clamp(0.0, 255.0), g.clamp(0.0, 255.0), b.clamp(0.0, 255.0))
    }

    pub fn to_color_name(&self) -> Option<String> {
        let hex = self.to_hex_string().to_lowercase();
        crate::commands::COLOR_NAMES.iter().find(|(_, h)| h.to_lowercase() == hex).map(|(name, _)| name.to_string())
