        return Ok(color);
    }

    anyhow::bail!("Unknown color format: {}", s)
}

fn parse_hex(hex: &str) -> anyhow::Result<Color> {
    if hex.len() < 6 {
        anyhow::bail!("Invalid hex color");
    }
    let r = u8::from_str_radix(&hex[0..2], 16)? as f64;
    let g = u8::from_str_radix(&hex[2..4], 16)? as f64;
    let b = u8::from_str_radix(&hex[4..6], 16)? as f64;
    Ok(Color::new(r, g, b))
}

fn parse_rgb(s: &str) -> anyhow::Result<Color> {
    let parts: Vec<&str> = s.split(',').map(|p| p.trim()).collect();
    if parts.len() < 3 {
        anyhow::bail!("Invalid RGB format");
    }
    let r: f64 = parts[0].parse()?;
    let g: f64 = parts[1].parse()?;
    let b: f64 = parts[2].parse()?;
    Ok(Color::new(r, g, b))
}

fn parse_rgba(s: &str) -> anyhow::Result<Color> {
    let parts: Vec<&str> = s.split(',').map(|p| p.trim()).collect();
    if parts.len() < 4 {
        anyhow::bail!("Invalid RGBA format");
    }
    let r: f64 = parts[0].parse()?;
    let g: f64 = parts[1].parse()?;
    let b: f64 = parts[2].parse()?;
    let a: f64 = parts[3].parse()?;
    Ok(Color::with_alpha(r, g, b, a))
}

fn parse_hsl(s: &str) -> anyhow::Result<Color> {
    let parts: Vec<&str> = s.split(',').map(|p| p.trim()).collect();
    if parts.len() < 3 {
        anyhow::bail!("Invalid HSL format");
    }
    let h: f64 = parts[0].parse()?;
    let s_str = parts[1].trim_end_matches('%').trim();
    let s: f64 = s_str.parse::<f64>()? / 100.0;
    let l_str = parts[2].trim_end_matches('%').trim();
    let l: f64 = l_str.parse::<f64>()? / 100.0;

    let (r, g, b) = crate::color::hsl_to_rgb(h, s, l);
    Ok(Color::new(r * 255.0, g * 255.0, b * 255.0))
}

fn parse_hsla(s: &str) -> anyhow::Result<Color> {
    let parts: Vec<&str> = s.split(',').map(|p| p.trim()).collect();
    if parts.len() < 4 {
        anyhow::bail!("Invalid HSLA format");
    }
    let h: f64 = parts[0].parse()?;
    let s_str = parts[1].trim_end_matches('%').trim();
    let s: f64 = s_str.parse::<f64>()? / 100.0;
    let l_str = parts[2].trim_end_matches('%').trim();
    let l: f64 = l_str.parse::<f64>()? / 100.0;
    let a_str = parts[3].trim_end_matches('%').trim();
    let a: f64 = a_str.parse()?;

    let (r, g, b) = crate::color::hsl_to_rgb(h, s, l);
    Ok(Color::with_alpha(r * 255.0, g * 255.0, b * 255.0, a))
}

fn parse_gray(s: &str) -> anyhow::Result<Color> {
    let val: f64 = s.trim_end_matches('%').trim().parse()?;
    let v = (val / 100.0 * 255.0) as f64;
    Ok(Color::new(v, v, v))
}

pub fn parse_color_name(name: &str) -> Option<Color> {
    for (color_name, hex) in crate::commands::COLOR_NAMES.iter() {
        if color_name.to_lowercase() == name.to_lowercase() {
            parse_hex(&hex[1..]).ok()
        } else {
            None
        }
    }?;
    None
}
