pub fn paint(color_str: &str, text: Vec<String>, bg_color: Option<String>, bold: bool, italic: bool, underline: bool, no_newline: bool) {
    let color = Color::parse(color_str).unwrap_or_else(|_| Color::new(255.0, 255.0, 255.0));

    let text_to_print = if text.is_empty() {
        use std::io::Read;
        let mut buffer = String::new();
        std::io::stdin().read_to_string(&mut buffer).ok();
        buffer
    } else {
        text.join(" ")
    };

    let (r, g, b) = color.to_rgb_array();

    let mut codes = format!("\x1b[38;2;{};{};{}m", r, g, b);

    if let Some(bg) = bg_color {
        if let Ok(bg_color) = Color::parse(&bg) {
            let (br, bg, bb) = bg_color.to_rgb_array();
            codes.push_str(&format!("\x1b[48;2;{};{};{}m", br, bg, bb));
        }
    }

    if bold {
        codes.push_str("\x1b[1m");
    }
    if italic {
        codes.push_str("\x1b[3m");
    }
    if underline {
        codes.push_str("\x1b[4m");
    }

    codes.push_str(&text_to_print);
    codes.push_str("\x1b[0m");

    if no_newline {
        print!("{}", codes);
    } else {
        println!("{}", codes);
    }
}
