fn read_colors(colors: &[String]) -> Result<Vec<Color>, String> {
    if colors.is_empty() {
        // Read from stdin
        let stdin = io::stdin();
        let reader = stdin.lock();
        let mut result = Vec::new();
        for line in reader.lines() {
            if let Ok(line) = line {
                let line = line.trim();
                if !line.is_empty() {
                    result.push(Color::parse(line)?);
                }
            }
        }
        Ok(result)
    } else {
        let mut result = Vec::new();
        for color_str in colors {
            result.push(Color::parse(color_str)?);
        }
        Ok(result)
    }
}

fn print_color(color: &Color) {
    println!("{}", color.to_hsl_string());
}

fn format_color(color: &Color, format: &str) -> Result<String, String> {
    match format {
        "hex" => Ok(color.to_hex_string()),
        "rgb" => Ok(color.to_rgb_string()),
        "rgb-float" => Ok(color.to_rgb_float_string()),
        "rgb-r" => Ok((color.r as u8).to_string()),
        "rgb-g" => Ok((color.g as u8).to_string()),
        "rgb-b" => Ok((color.b as u8).to_string()),
        "hsl" => Ok(color.to_hsl_string()),
        "hsl-hue" => Ok(format!("{}", color.to_hsl().0.round() as i32)),
        "hsl-saturation" => Ok(format!("{:.1}", color.to_hsl().1 * 100.0)),
        "hsl-lightness" => Ok(format!("{:.1}", color.to_hsl().2 * 100.0)),
        "hsv" => Ok(color.to_hsv_string()),
        "lch" => Ok(color.to_lch_string()),
        "oklch" => Ok(color.to_oklch_string()),
        "lab" => Ok(color.to_lab_string()),
        "oklab" => Ok(color.to_oklab_string()),
        "cmyk" => Ok(color.to_cmyk_string()),
        "name" => Ok(color.to_color_name().unwrap_or_else(|| color.to_hex_string())),
        _ => Err(format!("Unknown format: {}", format)),
    }
}

fn print_help() {
    println!("A command-line tool to generate, analyze, convert and manipulate colors\n");
    println!("Usage: executable [OPTIONS] <COMMAND>\n");
    println!("Commands:");
    println!("  color       Display information about the given color");
    println!("  colorblind  Simulate a color under a certain colorblindness profile");
    println!("  colorcheck  Check if your terminal emulator supports 24-bit colors.");
    println!("  complement  Get the complementary color (hue rotated by 180°)");
    println!("  darken      Darken color by a specified amount");
    println!("  desaturate  Decrease color saturation by a specified amount");
    println!("  distinct    Generate a set of visually distinct colors");
    println!("  format      Convert a color to the given format");
    println!("  gradient    Generate an interpolating sequence of colors");
    println!("  gray        Create a gray tone from a given lightness");
    println!("  help        Print this message or the help of the given subcommand(s)");
    println!("  lighten     Lighten color by a specified amount");
    println!("  list        Show a list of available color names");
    println!("  mix         Mix two colors in the given colorspace");
    println!("  paint       Print colored text using ANSI escape sequences");
    println!("  pick        Interactively pick a color from the screen (pipette)");
    println!("  random      Generate a list of random colors");
    println!("  rotate      Rotate the hue channel by the specified angle");
    println!("  saturate    Increase color saturation by a specified amount");
    println!("  set         Set a color property to a specific value");
    println!("  sort-by     Sort colors by the given property");
    println!("  textcolor   Get a readable text color for the given background color");
    println!("  to-gray     Completely desaturate a color (preserving luminance)\n");
    println!("Options:");
    println!("  -f, --force-color                  Alias for --mode=24bit");
    println!("  -h, --help                         Print help");
    println!("  -m, --color-mode <mode>            Specify the terminal color mode: 24bit, 8bit, off, *auto*");
    println!("  -V, --version                      Print version");
}
