                let (r, g, b) = oklab_to_rgb(l, a, b);
                Color::new(r * 255.0, g * 255.0, b * 255.0)
            },
            _ => { // Lab is default
                let (l1, a1, b1) = self.to_lab();
                let (l2, a2, b2) = other.to_lab();
                let l = l1 + (l2 - l1) * fraction;
                let a = a1 + (a2 - a1) * fraction;
                let b = b1 + (b2 - b1) * fraction;
                let (r, g, b) = lab_to_rgb(l, a, b);
                Color::new(r, g, b)
            }
        }
    }

    pub fn to_gray(&self) -> Color {
        let lum = self.luminance();
        let gray_val = if lum > 0.5 {
            255.0
        } else {
            0.0
        };
        Color::new(gray_val, gray_val, gray_val)
    }

    pub fn textcolor(&self) -> Color {
        let lum = self.luminance();
        if lum > 0.5 {
            Color::new(0.0, 0.0, 0.0)
        } else {
            Color::new(255.0, 255.0, 255.0)
        }
    }

    pub fn luminance(&self) -> f64 {
        let r = self.r / 255.0;
        let g = self.g / 255.0;
        let b = self.b / 255.0;

        let r = if r <= 0.03928 { r / 12.92 } else { ((r + 0.055) / 1.055).powf(2.4) };
        let g = if g <= 0.03928 { g / 12.92 } else { ((g + 0.055) / 1.055).powf(2.4) };
        let b = if b <= 0.03928 { b / 12.92 } else { ((b + 0.055) / 1.055).powf(2.4) };

        0.2126 * r + 0.7152 * g + 0.0722 * b
    }

    pub fn set_property(&self, property: &str, value: f64) -> Result<Color, String> {
        match property {
            "lightness" => {
                let (h, s, _) = self.to_hsl();
                let (r, g, b) = hsl_to_rgb(h, s, value);
                Ok(Color::new(r * 255.0, g * 255.0, b * 255.0))
            },
            "hue" => {
                let (_, s, l) = self.to_hsl();
                let (r, g, b) = hsl_to_rgb(value, s, l);
                Ok(Color::new(r * 255.0, g * 255.0, b * 255.0))
            },
            "hsl-hue" => self.set_property("hue", value),
            "hsl-saturation" => {
                let (h, _, l) = self.to_hsl();
                let (r, g, b) = hsl_to_rgb(h, value, l);
                Ok(Color::new(r * 255.0, g * 255.0, b * 255.0))
            },
            "hsl-lightness" => self.set_property("lightness", value),
            "red" => Ok(Color::new(value, self.g, self.b)),
            "green" => Ok(Color::new(self.r, value, self.b)),
            "blue" => Ok(Color::new(self.r, self.g, value)),
            "chroma" => {
                let (l, _, h) = self.to_lch();
                let (a, b) = lch_to_lab_ab(l, value, h);
                let (r, g, b) = lab_to_rgb(l, a, b);
                Ok(Color::new(r, g, b))
            },
            "lab-a" => {
                let (l, _, b) = self.to_lab();
                let (r, g, b) = lab_to_rgb(l, value, b);
                Ok(Color::new(r, g, b))
            },
            "lab-b" => {
                let (l, a, _) = self.to_lab();
                let (r, g, b) = lab_to_rgb(l, a, value);
                Ok(Color::new(r, g, b))
            },
            "oklab-l" => {
                let (_, a, b) = self.to_oklab();
                let (r, g, b) = oklab_to_rgb(value, a, b);
                Ok(Color::new(r * 255.0, g * 255.0, b * 255.0))
            },
            "oklab-a" => {
                let (l, _, b) = self.to_oklab();
                let (r, g, b) = oklab_to_rgb(l, value, b);
                Ok(Color::new(r * 255.0, g * 255.0, b * 255.0))
            },
            "oklab-b" => {
                let (l, a, _) = self.to_oklab();
                let (r, g, b) = oklab_to_rgb(l, a, value);
                Ok(Color::new(r * 255.0, g * 255.0, b * 255.0))
            },
            "alpha" => Ok(Color::with_alpha(self.r, self.g, self.b, value)),
            _ => Err(format!("Unknown property: {}", property)),
        }
    }

    pub fn gradient(colors: &[Color], count: usize, colorspace: &str) -> Vec<Color> {
        if colors.is_empty() {
            return vec![];
        }
        if colors.len() == 1 {
            return vec![colors[0].clone()];
        }
        if count == 0 {
            return vec![];
        }
        if count == 1 {
            return vec![colors[0].clone()];
        }

        let mut result = Vec::new();
        let segment_size = (count as f64 - 1.0) / (colors.len() - 1) as f64;

        for i in 0..count {
            let pos = i as f64 / segment_size;
            let seg_index = pos.floor() as usize;
            let seg_index = seg_index.min(colors.len() - 2);
            let frac = pos - seg_index as f64;

            let color = colors[seg_index].mix(&colors[seg_index + 1], frac, colorspace);
            result.push(color);
        }
        result
    }

    pub fn distinct(count: usize, initial: Option<Vec<Color>>, metric: &str) -> Vec<Color> {
        if count == 0 {
            return vec![];
        }

        let mut colors = if let Some(initial) = initial {
            if initial.len() >= count {
                return initial[..count].to_vec();
            }
            initial
        } else {
            vec![]
        };

        // Generate distinct colors by maximizing difference
        while colors.len() < count {
            let mut best_color = Color::random("vivid");
            let mut best_score = -1.0f64;

            for _ in 0..100 {
                let candidate = Color::random("vivid");
                let score: f64 = colors.iter().map(|c| color_distance(&candidate, c, metric)).sum();
                if score > best_score {
                    best_score = score;
                    best_color = candidate;
                }
            }

            colors.push(best_color);
        }

        colors[..count].to_vec()
    }

    pub fn sort_by(colors: &[Color], property: &str, reverse: bool, unique: bool) -> Vec<Color> {
        let mut sorted = colors.to_vec();

        if unique {
            sorted.sort_by(|a, b| {
                let (ar, ag, ab) = a.to_rgb_array();
                let (br, bg, bb) = b.to_rgb_array();
                ar.cmp(&br).then(ag.cmp(&bg)).then(ab.cmp(&bb))
            });
            sorted.dedup_by(|a, b| {
                let (ar, ag, ab) = a.to_rgb_array();
                let (br, bg, bb) = b.to_rgb_array();
                ar == br && ag == bg && ab == bb
            });
        }

        match property {
            "hue" => {
                sorted.sort_by(|a, b| {
                    let (h1, _, _) = a.to_hsl();
                    let (h2, _, _) = b.to_hsl();
                    h1.partial_cmp(&h2).unwrap()
                });
            },
            "brightness" => {
                sorted.sort_by(|a, b| {
                    let (_, _, v1) = a.to_hsv();
                    let (_, _, v2) = b.to_hsv();
                    v1.partial_cmp(&v2).unwrap()
                });
            },
            "luminance" => {
                sorted.sort_by(|a, b| {
                    let l1 = a.luminance();
                    let l2 = b.luminance();
                    l1.partial_cmp(&l2).unwrap()
                });
            },
            "chroma" => {
                sorted.sort_by(|a, b| {
                    let (_, c1, _) = a.to_lch();
                    let (_, c2, _) = b.to_lch();
                    c1.partial_cmp(&c2).unwrap()
                });
            },
            "random" => {
                // Simple shuffle using system time
                use std::time::{SystemTime, UNIX_EPOCH};
                let nanos = SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .map(|d| d.as_nanos())
                    .unwrap_or(0);

                let mut seed = nanos as u64;
                for i in (1..sorted.len()).rev() {
                    seed = seed.wrapping_mul(1664525).wrapping_add(1013904223);
                    let j = (seed as usize) % (i + 1);
                    sorted.swap(i, j);
                }
            },
            _ => {},
        }

        if reverse {
            sorted.reverse();
        }

        sorted
    }

    pub fn colorblind(&self, colorblind_type: &str) -> Color {
        // Colorblind simulation matrices
        let (r, g, b) = match colorblind_type {
            "prot" | "protanopia" => {
                // Protanopia (red-blind)
                let r = 0.567 * self.r + 0.433 * self.g;
                let g = 0.558 * self.r + 0.442 * self.g;
                let b = 0.0 * self.r + 0.242 * self.b;
                (r, g, b)
            },
            "deuter" | "deuteranopia" => {
                // Deuteranopia (green-blind)
                let r = 0.625 * self.r + 0.375 * self.g;
                let g = 0.7 * self.r + 0.3 * self.g;
                let b = 0.0 * self.r + 1.0 * self.b;
                (r, g, b)
            },
            "trit" | "tritanopia" => {
                // Tritanopia (blue-blind)
                let r = 0.95 * self.r + 0.05 * self.b;
                let g = 0.433 * self.r + 0.567 * self.g;
                let b = 0.475 * self.g + 0.525 * self.b;
                (r, g, b)
            },
            _ => (self.r, self.g, self.b),
        };

        Color::new(r.clamp(0.0, 255.0), g.clamp(0.0, 255.0), b.clamp(0.0, 255.0))
    }

    pub fn to_color_name(&self) -> Option<String> {
        let hex = self.to_hex_string().to_lowercase();
        crate::commands::COLOR_NAMES.iter().find(|(_, h)| h.to_lowercase() == hex).map(|(name, _)| name.to_string())
    }
}

// Color space conversion functions

pub fn hsl_to_rgb(h: f64, s: f64, l: f64) -> (f64, f64, f64) {
    if s == 0.0 {
        return (l, l, l);
    }

    let h = h % 360.0;
    let h = if h < 0.0 { h + 360.0 } else { h };

    let c = (1.0 - (2.0 * l - 1.0).abs()) * s;
    let h_prime = h / 60.0;
    let x = c * (1.0 - (h_prime % 2.0 - 1.0).abs());

    let (r1, g1, b1) = match h_prime as i32 {
        0 => (c, x, 0.0),
        1 => (x, c, 0.0),
        2 => (0.0, c, x),
        3 => (0.0, x, c),
        4 => (x, 0.0, c),
        _ => (c, 0.0, x),
    };

    let m = l - c / 2.0;
    (r1 + m, g1 + m, b1 + m)
}

pub fn rgb_to_xyz(r: f64, g: f64, b: f64) -> (f64, f64, f64) {
    let r = (r / 255.0).powf(2.2);
    let g = (g / 255.0).powf(2.2);
    let b = (b / 255.0).powf(2.2);

    let x = r * 0.4124564 + g * 0.3575761 + b * 0.1804375;
    let y = r * 0.2126729 + g * 0.7151522 + b * 0.0721750;
    let z = r * 0.0193339 + g * 0.1191920 + b * 0.9503041;

    (x, y, z)
}

pub fn xyz_to_rgb(x: f64, y: f64, z: f64) -> (f64, f64, f64) {
    let r = x * 3.2404542 + y * -1.5371385 + z * -0.4985314;
    let g = x * -0.9692660 + y * 1.8760108 + z * 0.0415560;
    let b = x * 0.0556434 + y * -0.2040259 + z * 1.0572252;

    let r = r.max(0.0).powf(1.0 / 2.2) * 255.0;
    let g = g.max(0.0).powf(1.0 / 2.2) * 255.0;
    let b = b.max(0.0).powf(1.0 / 2.2) * 255.0;

    (r, g, b)
}

pub fn xyz_to_lab(x: f64, y: f64, z: f64) -> (f64, f64, f64) {
    let xn = 0.95047;
    let yn = 1.0;
    let zn = 1.08883;

    let x = x / xn;
    let y = y / yn;
    let z = z / zn;

    let f = |t: f64| if t > 0.008856 { t.powf(1.0 / 3.0) } else { 7.787 * t + 16.0 / 116.0 };

    let l = 116.0 * f(y) - 16.0;
    let a = 500.0 * (f(x) - f(y));
    let b = 200.0 * (f(y) - f(z));

    (l, a, b)
}

pub fn lab_to_xyz(l: f64, a: f64, b: f64) -> (f64, f64, f64) {
    let xn = 0.95047;
    let yn = 1.0;
    let zn = 1.08883;

    let fy = (l + 16.0) / 116.0;
    let fx = a / 500.0 + fy;
    let fz = fy - b / 200.0;

    let f_inv = |t: f64| {
        let t3 = t * t * t;
        if t3 > 0.008856 { t3 } else { (t - 16.0 / 116.0) / 7.787 }
    };

    let x = xn * f_inv(fx);
    let y = yn * f_inv(fy);
    let z = zn * f_inv(fz);

    (x, y, z)
}

pub fn lab_to_rgb(l: f64, a: f64, b: f64) -> (f64, f64, f64) {
    let (x, y, z) = lab_to_xyz(l, a, b);
    xyz_to_rgb(x, y, z)
}

pub fn lab_to_lch(l: f64, a: f64, b: f64) -> (f64, f64, f64) {
    let c = (a * a + b * b).sqrt();
    let h = b.atan2(a) * 180.0 / PI;
    let h = if h < 0.0 { h + 360.0 } else { h };
    (l, c, h)
}

pub fn lch_to_lab_ab(l: f64, c: f64, h: f64) -> (f64, f64) {
    let h_rad = h * PI / 180.0;
    let a = c * h_rad.cos();
    let b = c * h_rad.sin();
    (a, b)
}

pub fn lch_to_rgb(l: f64, c: f64, h: f64) -> (f64, f64, f64) {
    let (a, b) = lch_to_lab_ab(l, c, h);
    lab_to_rgb(l, a, b)
}

pub fn xyz_to_oklab(x: f64, y: f64, z: f64) -> (f64, f64, f64) {
    let l_ = 0.4122214708 * x + 0.5291605794 * y + 0.0433812999 * z;
    let m_ = 0.2119034982 * x + 0.6806995451 * y + 0.1073969566 * z;
    let s_ = 0.0883024619 * x + 0.0817845529 * y + 0.8943868922 * z;

    let l = l_.cbrt();
    let m = m_.cbrt();
    let s = s_.cbrt();

    let l_out = 0.2104542553 * l + 0.7936177850 * m - 0.0040720468 * s;
    let a = 1.9779984951 * l - 2.4285922050 * m + 0.4505937099 * s;
    let b = 0.0259040371 * l + 0.7827717662 * m - 0.8086757660 * s;

    (l_out, a, b)
}

pub fn oklab_to_xyz(l: f64, a: f64, b: f64) -> (f64, f64, f64) {
    let l_ = l + 0.3963377774 * a + 0.2158037573 * b;
    let m_ = l - 0.1055613458 * a - 0.0638541728 * b;
    let s_ = l - 0.0894841775 * a - 1.2914855480 * b;

    let l = l_ * l_ * l_;
    let m = m_ * m_ * m_;
    let s = s_ * s_ * s_;

    let x = 4.0767416621 * l - 3.3077363322 * m + 0.2309101289 * s;
    let y = -1.2684380046 * l + 2.6097574011 * m - 0.3413193761 * s;
    let z = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s;

    (x, y, z)
}

pub fn oklab_to_rgb(l: f64, a: f64, b: f64) -> (f64, f64, f64) {
    let (x, y, z) = oklab_to_xyz(l, a, b);
    xyz_to_rgb(x, y, z)
}

pub fn color_distance(c1: &Color, c2: &Color, metric: &str) -> f64 {
    match metric {
        "CIE76" => {
            let (l1, a1, b1) = c1.to_lab();
            let (l2, a2, b2) = c2.to_lab();
            ((l1 - l2) * (l1 - l2) + (a1 - a2) * (a1 - a2) + (b1 - b2) * (b1 - b2)).sqrt()
        },
        "CIEDE2000" => {
            // Simplified CIEDE2000
            let (l1, a1, b1) = c1.to_lab();
            let (l2, a2, b2) = c2.to_lab();
            ((l1 - l2) * (l1 - l2) + (a1 - a2) * (a1 - a2) + (b1 - b2) * (b1 - b2)).sqrt()
        },
        _ => {
            let (l1, a1, b1) = c1.to_lab();
            let (l2, a2, b2) = c2.to_lab();
            ((l1 - l2) * (l1 - l2) + (a1 - a2) * (a1 - a2) + (b1 - b2) * (b1 - b2)).sqrt()
        }
    }
}
